                    onClick = {
                        scope.launch {
                            while (progress < 1f) {
                                progress += 0.1f
                                delay(1000L)
                            }
                        }
                    }
                ) { Text("Запустить", fontSize = 22.sp) }
                LinearProgressIndicator(
                    progress = progress,
                    color = Color.DarkGray,
                    trackColor = Color.LightGray
                )
            }
        }
    }
}
```



