        OutlinedTextField(value = userAge.toString(), modifier=Modifier.padding(8.dp), label = {Text("Enter an age")},
            onValueChange = {changeAge(it)},
            keyboardOptions = KeyboardOptions(keyboardType= KeyboardType.Number)
        )
