### Передача сложных данных



Аналогичным способом можно передавать и набор разнотипных данных. Например, в MainActivity передадим несколько данных:



```kotlin

package com.example.helloapp

import android.content.Intent
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.material3.Button
import androidx.compose.material3.Text
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.unit.sp

class MainActivity : ComponentActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        setContent {
            // Получаем текущий Context
            val context = LocalContext.current
            Button(onClick = {
                val intent = Intent(context, SecondActivity::class.java)

                // передаем несколько данных
                intent.putExtra("name", "Tom")
                intent.putExtra("age", 41)
                intent.putExtra("company", "Google")

                context.startActivity(intent)
                
            }){ Text("Go To", fontSize = 20.sp)  }
        }
    }
}
```



В SecondActivity получим эти данные:



```kotlin

package com.example.helloapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.Column
import androidx.compose.material3.Text
import androidx.compose.ui.unit.sp

class SecondActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        setContent {
            val userName = intent.getStringExtra("name") ?: ""
            val userAge = intent.getIntExtra("age", 0) // второй параметр - значение по умолчанию
            val company = intent.getStringExtra("company") ?: ""
            Column {
                Text("Name: ${userName}", fontSize = 22.sp)
                Text("Age: ${userAge}", fontSize = 22.sp)
                Text("Company: ${company}", fontSize = 22.sp)
            }
        }
    }
}
```




